/**
 * Worker entry: the OpenNext-built Next.js app behind the Google sign-in
 * gate (lib/auth/gate.ts), plus a cron handler that runs the scheduled
 * jobs (lib/scheduled.ts).
 */

// Generated by `npm run cf:build`, so it is missing until a build runs. The
// OpenNext docs use @ts-ignore here: @ts-expect-error fails once it exists.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as app } from "./.open-next/worker.js";
import { gate, type AuthEnv } from "./lib/auth/gate";
import { runCronJobs } from "./lib/scheduled";

const worker = {
  fetch: (request: Request, env: AuthEnv, ctx: unknown) =>
    gate(request, env, (r) => app.fetch(r, env, ctx)),
  scheduled: (_controller: unknown, env: object, ctx: unknown) =>
    runCronJobs(app.fetch, env, ctx),
};

export default worker;
